}
directories=[
 Path('/etc/systemd/system'),Path('/lib/systemd/system'),Path('/etc/nginx'),
 Path('/etc/cron.d'),Path('/etc/cron.daily'),Path('/etc/cron.hourly'),Path('/etc/cron.weekly'),
 Path('/usr/local/bin'),Path('/srv/projects/VPS'),Path('/srv/projects/Codex'),
