refs={k:[] for k in T}
paths_scanned=0;total_skipped=0
for base in directories:
 if not base.is_dir():continue
 for cur,dirs,files in os.walk(base,followlinks=False):
  dirs[:]=[v for v in dirs if v not in SKIP and not (Path(cur)/v).is_symlink()]
  for file in files:
   p=Path(cur)/file
   if p.is_symlink() or p.suffix.lower() not in EXT:continue
   try:
    if p.stat().st_size>500000:continue
    data=p.read_bytes()
   except (OSError,PermissionError):continue
   paths_scanned+=1
   for k,target in T.items():
    if os.fsencode(str(target)) in data and len(refs[k])<60:
     refs[k].append(str(p)[:180])
  if paths_scanned>14000:
   total_skipped+=1;break
 if total_skipped:break
ignore={os.getpid()};pid=os.getppid()
while pid>1 and pid not in ignore:
 ignore.add(pid)
 try:
  m=re.search(r'(?m)^PPid:\s*(\d+)$',(Path('/proc')/str(pid)/'status').read_text())
  pid=int(m.group(1)) if m else 0
 except OSError:break
proc={k:[] for k in T}
for p in Path('/proc').iterdir():
 if not p.name.isdecimal() or int(p.name) in ignore:continue
 try:
  args=(p/'cmdline').read_bytes();cwd=os.readlink(p/'cwd');exe=os.readlink(p/'exe')
 except OSError:continue
 for k,path in T.items():
